	the Limbus weapons (Skia / Arctus / Auge / Telognophos / Daduchos / Telopanos). Windower can't read these from the
	item (only the rank), so InfoGear adds them from here. ranks[r] = bonus at rank r.

	Source: R30 values per slot from the user's sheet of the BG-Wiki pages (the NQ / HQ1 / HQ2 of a slot share them).
	Every armor piece follows one growth rule (all sets, slots and tiers rank up the same way; it depends only on a
	stat's R30 value). It reproduces the BG-Wiki tables of Sworn Crown / Sabatons, Prestige Platemail, Duty Crown,
	Clemency Somen and Revelation Platemail (139 of 141 values; the 2 others contradict tables with the same max, so
	they look like wiki typos). The Bravery set starts [2] at R16 and [3] at R26 (Indomitable Sabots).
	[1] +1 per rank from R1; [2] from R15 and [3] from R20, +1 every 2 ranks but at most the R30 value minus 1 per
	3 ranks still to go; [4] (pet) from R1. Weapons (BG-Wiki, Telopanos Grip):
	every group from R1; +30 stats +1 per rank, bigger ones on the grip's HP curve (4 / 3 / 2 per 100 at R1-15 / 16-25 /
	26-30), so the grips are exact. Exact at R30. Not shown: Damage, Magic Damage, Blood Pact damage, pet stats.
]]
